import { candidates } from "@sudoku/stores/candidates";

/**
 * 命令模式基类
 * 该基类定义了命令对象的基本接口，包括执行、撤销和重做操作
 */
class Command {
	/**
	 * 执行命令
	 * @returns {boolean} 如果命令成功执行返回 true，否则返回 false
	 */
	execute() {
		throw new Error("execute() 必须在子类中实现");
	}

	/**
	 * 撤销命令
	 */
	undo() {
		throw new Error("undo() 必须在子类中实现");
	}

	/**
	 * 重做命令
	 */
	redo() {
		throw new Error("redo() 必须在子类中实现");
	}

	/**
	 * 检查命令是否与另一个命令等效（用于去重）
	 * @param {Command} otherCommand 另一个命令对象
	 * @returns {boolean} 如果两个命令等效返回 true
	 */
	isEquivalentTo(otherCommand) {
		return false;
	}
}

/**
 * 设置数字命令
 * 用于在数独网格的指定位置设置数字
 */
class SetNumberCommand extends Command {
	/**
	 * @param {Object} gridStore Svelte store 更新函数的引用
	 * @param {Object} pos 位置对象 {x, y}
	 * @param {number} newValue 新值 (0-9)
	 * @param {number} oldValue 旧值 (0-9)
	 */
	constructor(gridStore, pos, newValue, oldValue) {
		super();
		this.gridStore = gridStore; // 存储对 grid store 的引用
		this.pos = pos; // 位置 {x, y}
		this.newValue = newValue; // 新值
		this.oldValue = oldValue; // 旧值
	}

	/**
	 * 执行命令：在指定位置设置新值
	 * @returns {boolean} 如果值发生变化返回 true，否则返回 false
	 */
	execute() {
		// 如果新值和旧值相同，不执行任何操作
		if (this.newValue === this.oldValue) {
			return false;
		}

		// 更新网格
		this.gridStore.update($grid => {
			$grid[this.pos.y][this.pos.x] = this.newValue;
			return $grid;
		});

		return true;
	}

	/**
	 * 撤销命令：恢复到旧值
	 */
	undo() {
		this.gridStore.update($grid => {
			$grid[this.pos.y][this.pos.x] = this.oldValue;
			return $grid;
		});
		
		// 撤销后，如果恢复为非零值，清除候选显示
		// if (this.oldValue !== 0) {
		// 	candidates.clear(this.pos);
		// }
	}

	/**
	 * 重做命令：重新设置为新值
	 */
	redo() {
		this.gridStore.update($grid => {
			$grid[this.pos.y][this.pos.x] = this.newValue;
			return $grid;
		});
		
		// 当重做填入数字时，清除该位置的候选值显示，防止显示为高亮候选状态
		// if (this.newValue !== 0) {
		// 	candidates.clear(this.pos);
		// }
	}

	/**
	 * 检查两个命令是否等效
	 * 如果位置相同且新值相同，则认为是等效命令
	 * @param {Command} otherCommand 另一个命令对象
	 * @returns {boolean} 如果等效返回 true
	 */
	isEquivalentTo(otherCommand) {
		if (!(otherCommand instanceof SetNumberCommand)) {
			return false;
		}

		return (
			this.pos.x === otherCommand.pos.x &&
			this.pos.y === otherCommand.pos.y &&
			this.newValue === otherCommand.newValue
		);
	}
}

/**
 * 分支对象
 * 表示回溯树中的一个分支点，每个分支维护独立的 undo/redo 栈
 */
class Branch {
	/**
	 * @param {Object|null} branchPoint 分支点信息 {pos, value}
	 */
	constructor(branchPoint = null) {
		this.branchPoint = branchPoint; // 分支点 {pos, value}
		this.undoStack = []; // 该分支的撤销栈
		this.redoStack = []; // 该分支的重做栈
		this.disabledCandidates = new Map(); // 该分支禁用的候选值
	}

	/**
	 * 添加命令到撤销栈
	 * @param {Command} command 要添加的命令
	 */
	pushUndo(command) {
		this.undoStack.push(command);
	}

	/**
	 * 从撤销栈弹出命令
	 * @returns {Command|undefined} 弹出的命令，如果栈为空返回 undefined
	 */
	popUndo() {
		return this.undoStack.pop();
	}

	/**
	 * 添加命令到重做栈
	 * @param {Command} command 要添加的命令
	 */
	pushRedo(command) {
		this.redoStack.push(command);
	}

    unshiftRedo(command) {
        this.redoStack.unshift(command);
    }

	/**
	 * 从重做栈弹出命令
	 * @returns {Command|undefined} 弹出的命令，如果栈为空返回 undefined
	 */
	popRedo() {
		return this.redoStack.pop();
	}

	/**
	 * 检查是否可以撤销
	 * @returns {boolean} 如果撤销栈不为空返回 true
	 */
	canUndo() {
		return this.undoStack.length > 0;
	}

	/**
	 * 检查是否可以重做
	 * @returns {boolean} 如果重做栈不为空返回 true
	 */
	canRedo() {
		return this.redoStack.length > 0;
	}

	/**
	 * 清空该分支的所有历史
	 */
	clear() {
		this.undoStack = [];
		this.redoStack = [];
		this.disabledCandidates.clear();
	}
}

/**
 * 历史管理器
 * 管理命令历史和分支回溯逻辑
 */
class HistoryManager {
	/**
	 * @param {Object} gridStore Svelte store 的引用
	 */
	constructor(gridStore) {
		this.gridStore = gridStore;
		this.currentBranch = new Branch(); // 当前活动分支
		this.branchStack = []; // 分支栈，用于回溯
	}

	/**
	 * 执行命令并添加到历史记录
	 * @param {Command} command 要执行的命令
	 * @returns {boolean} 如果命令成功执行返回 true
	 */
	execute(command) {
		// 检查是否与上一个命令等效（防止重复记录）
		if (this.currentBranch.undoStack.length > 0) {
			const lastCommand = this.currentBranch.undoStack[this.currentBranch.undoStack.length - 1];
			if (command.isEquivalentTo(lastCommand)) {
				return false;
			}
		}

		// 执行命令
		const success = command.execute();
		if (success) {
			// 只有成功执行的命令才加入当前分支的 undo 栈
			this.currentBranch.pushUndo(command);

            // 清空重做栈（因为新操作使得之前的重做历史失效）
		    this.currentBranch.redoStack = [];

            // 同时将执行命令加入历史分支的 redo 栈
            for (const branch of this.branchStack) {
                branch.unshiftRedo(command);
            }
		}

		return success;
	}

	/**
	 * 撤销操作
	 * @returns {boolean} 如果成功撤销返回 true
	 */
	undo() {
		if (!this.currentBranch.canUndo()) {
			return false;
		}

		const command = this.currentBranch.popUndo();
		command.undo();
		this.currentBranch.pushRedo(command);

		return true;
	}

	/**
	 * 重做操作
	 * @returns {boolean} 如果成功重做返回 true
	 */
	redo() {
		if (!this.currentBranch.canRedo()) {
			return false;
		}

		const command = this.currentBranch.popRedo();
		command.redo();
		this.currentBranch.pushUndo(command);

		return true;
	}

	/**
	 * 创建新分支（当用户选择候选值时调用）
	 * @param {Object} branchPoint 分支点信息 {pos, value}
	 */
	createBranch(branchPoint) {
		const newBranch = new Branch(branchPoint);
		this.branchStack.push(this.currentBranch);
		this.currentBranch = newBranch;
	}

	/**
	 * 回溯到上一个分支点
	 * @returns {boolean} 如果成功回溯返回 true
	 */
	backToBranch() {
		if (this.branchStack.length === 0) {
			return false;
		}

		// 撤销当前分支的所有操作
		while (this.currentBranch.canUndo()) {
			const command = this.currentBranch.popUndo();
			command.undo();
		}

        // 切换回父分支
		const branchPoint = this.currentBranch.branchPoint;
		this.currentBranch = this.branchStack.pop();

		// 记录错误的分支选择
		if (branchPoint) {
			const { pos, value } = branchPoint;
			const cellKey = `${pos.y},${pos.x}`;

			// 在父分支中禁用这个错误的候选值
			if (!this.currentBranch.disabledCandidates.has(cellKey)) {
				this.currentBranch.disabledCandidates.set(cellKey, new Set());
			}
			this.currentBranch.disabledCandidates.get(cellKey).add(value);
		}

		return [true, branchPoint?.pos];
	}

	/**
	 * 检查是否可以撤销
	 * @returns {boolean}
	 */
	canUndo() {
		return this.currentBranch.canUndo();
	}

	/**
	 * 检查是否可以重做
	 * @returns {boolean}
	 */
	canRedo() {
		return this.currentBranch.canRedo();
	}

	/**
	 * 检查是否可以回溯到分支点
	 * @returns {boolean}
	 */
	canBackToBranch() {
		return this.branchStack.length > 0;
	}

	/**
	 * 获取当前分支禁用的候选值
	 * @returns {Map} 禁用候选值的 Map
	 */
	getDisabledCandidates() {
		return this.currentBranch.disabledCandidates;
	}

	getBranchCount() {
		return this.branchStack.length;
	}

	/**
	 * 重置历史管理器（开始新游戏时调用）
	 */
	reset() {
		this.currentBranch = new Branch();
		this.branchStack = [];
	}
}

export { Command, SetNumberCommand, Branch, HistoryManager };
